        AND phone LIKE CONCAT('%', #{phone}, '%')


        AND add_by = #{addBy}


        AND enabled = #{enabled}


        AND if_out_source = #{ifOutSource}


        AND truename LIKE CONCAT('%', #{truename}, '%')


        AND field_id = #{fieldId}


        AND province = #{province}


        AND company = #{company}


        AND department = #{department}


        AND groupname = #{groupname}


        AND is_admin = #{isAdmin}


