UPDATE et_user
username = #{username}, password = #{password}, email = #{email}, phone = #{phone}, add_date = #{addDate}, expire_date = #{expireDate}, add_by = #{addBy}, enabled = #{enabled}, if_out_source = #{ifOutSource}, truename = #{truename}, field_id = #{fieldId}, province = #{province}, company = #{company}, department = #{department}, groupname = #{groupname}, is_admin = #{isAdmin},
WHERE id = #{id}

UPDATE et_user
SET is_admin = #{isAdmin}
WHERE id = #{userId}

UPDATE et_user
SET enabled = NOT #{isDisabled}
WHERE id = #{userId}

